def hold(folder):
    errors=[]
    for args in [('stop','gateway'),('stop','-t','90','game')]:
        try:r.compose(*args)
        except BaseException as e:errors.append(type(e).__name__)
    save(folder/('held-'+str(time.time_ns())+'.json'),{'errors':errors,'database_restored':False})
